# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: gather
def gather(xs, floor_=6):
    return [v for v in xs if v > floor_]

# region: digest
def digest(xs, factor=3):
    return [v * factor for v in xs]

# region: shape
def shape(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(emit(shape(digest(gather(sift(raw))))))

